@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSubscription: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Subscription

    public static func lift(_ handle: UInt64) throws -> Subscription {
        return Subscription(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Subscription) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Subscription {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Subscription, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSubscription_lift(_ handle: UInt64) throws -> Subscription {
    return try FfiConverterTypeSubscription.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSubscription_lower(_ value: Subscription) -> UInt64 {
    return FfiConverterTypeSubscription.lower(value)
}






public protocol SyncCoreProtocol: AnyObject, Sendable {
    
    /**
     * Teaches the endpoint another device's address (from `local_address`).
     */
    func addPeerAddress(address: String) throws 
    
    func addReaction(id: String, reaction: String) throws 
    
    /**
     * Signs an agent card naming this device as the agent's host and this device's user, for
     * the host app to serve on the agent's public URL. Valid for `ttl_ms`.
     */
    func agentCard(agentSecret: Data, ttlMs: UInt64) throws  -> String
    
    /**
     * The scope's agent members, with their hosts.
     */
    func agents(scope: String) throws  -> [AgentInfo]
    
    func apiVersion()  -> UInt32
    
    /**
     * Admits a device of this user that is known but not yet in every scope (for example
     * one recovered from the phrase). Returns the scopes it was added to.
     */
    func approveDevice(device: String) throws  -> [String]
    
    /**
     * Assigns an agent (by its secp256k1 secret) to a scope, hosted by `host` or this device.
     */
    func assignAgent(scope: String, agentSecret: Data, host: String?, role: MemberRole, ttlMs: UInt64) throws  -> String
    
    /**
     * Closes the pairing offer. A new device waiting on its confirmation is told.
     */
    func cancelPairing() 
    
    func changeRole(scope: String, principal: String, role: MemberRole) throws 
    
    /**
     * Stops networking, flushes and releases the data directory. Further calls fail with `Closed`.
     */
    func close() async throws 
    
    /**
     * The user checked that `device` shows the same number as this device
     * (`CoreEvent::PairingConfirmation`). Call it on both devices: the existing one hands
     * over the identity only once both have. Fails with `Pairing` if no confirmation with
     * that device is waiting.
     */
    func confirmPairing(device: String) throws 
    
    func conversation(scope: String) throws  -> Conversation?
    
    func conversations() throws  -> [Conversation]
    
    /**
     * Conversations matching `filter`, in list order (pinned, then manual order, then recent).
     */
    func conversationsFiltered(filter: ConversationFilter) throws  -> [Conversation]
    
    func createConversation(title: String, replication: Replication) throws  -> String
    
    /**
     * A one-time invite link for `scope`.
     */
    func createInvite(scope: String, role: MemberRole, ttlMs: UInt64) throws  -> String
    
    /**
     * An invite only `user` can redeem, for sending over a channel others can read, such as an
     * agent's public URL. Only this device can admit with it.
     */
    func createInviteFor(scope: String, user: String, role: MemberRole, ttlMs: UInt64) throws  -> String
    
    func createWorkspace(title: String) throws  -> String
    
    /**
     * Deletes a device-local conversation outright. Leave a synced one instead.
     */
    func deleteLocalConversation(scope: String) throws 
    
    func deleteMessage(id: String) throws 
    
    func deviceKey()  -> String
    
    func devices() throws  -> [Device]
    
    func diagnostics()  -> Diagnostics
    
    func editMessage(id: String, content: String) throws 
    
    /**
     * Writes a conversation to the directory `path` (created if needed) as
     * `conversation.json`, with its downloaded attachments under `attachments/`. Only what
     * this device holds is included.
     */
    func exportConversation(scope: String, path: String) async throws  -> ExportSummary
    
    /**
     * Path to a decrypted copy of the attachment, downloading it from a peer if needed. The
     * copy lives in a cache that is trimmed past its cap and cleared when the core closes.
     */
    func fetchAttachment(scope: String, hash: String) async throws  -> String
    
    /**
     * Imports a conversation from the app's own store, keeping its timestamps in the HLC.
     * Each call creates a new conversation; record the returned id to avoid importing twice.
     */
    func importLegacyConversation(conversation: LegacyConversation, messages: [LegacyMessage]) throws  -> String
    
    /**
     * Adds a user by key.
     */
    func invite(scope: String, user: String, role: MemberRole) throws 
    
    func isOnline()  -> Bool
    
    /**
     * Leaves a conversation: removes this user from its members and deletes the local copy
     * once another device has the removal. Other members keep theirs; an invite brings it
     * back. The last owner of a shared conversation has to make someone else an owner first
     * (`PermissionDenied`). This user's other devices stop listing it.
     */
    func leaveConversation(scope: String) throws 
    
    /**
     * The live state every device currently holds in a conversation, this device's
     * included, ordered by namespace and device.
     */
    func liveState(scope: String) throws  -> [LiveState]
    
    /**
     * This device's direct addresses, for QR payloads or setups without discovery.
     */
    func localAddress()  -> String?
    
    func markRead(scope: String, hlc: UInt64) throws 
    
    func message(id: String) throws  -> Message?
    
    /**
     * One page of messages, oldest first. Pass `next_cursor` as `before` to page back.
     */
    func messages(scope: String, before: PageCursor?, limit: UInt32) throws  -> MessagePage
    
    /**
     * Starts streaming a response. Tokens go to connected devices directly and are never
     * stored; `finish` commits the final message under the stream's id.
     */
    func openStream(scope: String, role: MessageRole, asAgent: String?) throws  -> OutgoingStream
    
    /**
     * On the new device: joins using a scanned payload, or `osaurus-pair:2:<device>:<code>`
     * built from a typed code. A current host answers with `CoreEvent::PairingConfirmation`;
     * completion arrives as `CoreEvent::Paired` or `PairingFailed`. A payload from a host
     * older than 0.1.0-beta.6 (`osaurus-pair:1:`) still pairs, without the confirmation.
     */
    func pairWithOffer(payload: String) async throws 
    
    /**
     * Starts pairing on this (existing) device. Show `payload` as a QR code or `code` for
     * typing. Valid for `ttl_ms`. A new offer replaces the previous one. When a new device
     * connects with the code, `CoreEvent::PairingConfirmation` arrives here and there.
     */
    func pairingOffer(ttlMs: UInt64) throws  -> PairingOffer
    
    /**
     * Makes a device-local conversation synced: this user's other devices get it, with its
     * history.
     */
    func promoteToSynced(scope: String) throws 
    
    /**
     * Publishes a signed record in this device's discovery entry naming it as the agent's
     * host. Pass None to withdraw.
     */
    func publishAgentRecord(agentSecret: Data?, ttlMs: UInt64) throws  -> String?
    
    /**
     * The decrypted bytes of an attachment (or app data blob), downloading it from a peer if
     * needed. Unlike `fetch_attachment`, no plaintext copy is written to disk.
     */
    func readAttachment(scope: String, hash: String) async throws  -> Data
    
    /**
     * Replaces this device's user identity with the one derived from the phrase. Existing
     * local conversations are kept and shared with the recovered identity, and history sealed
     * to that identity's recovery key (including a restored database's) becomes readable.
     */
    func recoverFromPhrase(phrase: String) throws 
    
    /**
     * Whether this data directory was restored from another device's backup and its history
     * is waiting for that identity's recovery phrase. Also signalled by `RecoveryAvailable`.
     */
    func recoveryAvailable() throws  -> Bool
    
    func recoveryPhrase() throws  -> [String]
    
    /**
     * Redeems an invite. The result arrives as `CoreEvent::InviteResult`.
     */
    func redeemInvite(token: String) throws 
    
    /**
     * The numbers differ, or the user backed out. Ends pairing with `device`, which gets
     * `PairingFailed`. On the existing device the offer closes too, since whoever reached
     * the confirmation knew the code.
     */
    func rejectPairing(device: String) throws 
    
    func remove(scope: String, principal: String) throws 
    
    func removeReaction(id: String, reaction: String) throws 
    
    func renameConversation(scope: String, title: String) throws 
    
    /**
     * Fetches `days` of history older than `before_hlc` at high priority.
     */
    func requestHistory(scope: String, beforeHlc: UInt64, days: UInt32) throws 
    
    /**
     * Signs this device out: stops networking, deletes the data directory and this core's key
     * store entries. Conversations stay on other devices and with other members; to stop
     * this device being admitted again, revoke it from another device. Further calls fail
     * with `Closed`; open a new core to start over.
     */
    func reset() async throws 
    
    /**
     * Looks up the agent a device publishes as host. Returns the verified agent id.
     */
    func resolveAgent(host: String) async throws  -> String?
    
    /**
     * Rebinds the endpoint, reconnects and catches up.
     */
    func resume() async throws 
    
    /**
     * Revokes `devices` (a stolen one, say) and replaces the user identity, so the old secret
     * they hold no longer admits anyone. This user's other devices take on the new identity
     * when they next connect to one that has it. The recovery phrase changes too.
     */
    func revokeAndRotate(devices: [String]) throws  -> IdentityRotation
    
    /**
     * Revokes a lost or wiped device. A revoked device keeps the user secret, so for a stolen
     * device use `revoke_and_rotate`.
     */
    func revokeDevice(device: String) throws 
    
    func search(query: String, limit: UInt32) throws  -> [SearchResult]
    
    /**
     * Full-text search within conversations matching `filter`.
     */
    func searchFiltered(query: String, filter: ConversationFilter, limit: UInt32) throws  -> [SearchResult]
    
    func sendMessage(scope: String, message: OutgoingMessage) throws  -> String
    
    func setArchived(scope: String, archived: Bool) throws 
    
    func setBackfillPolicy(policy: BackfillPolicy) throws 
    
    /**
     * Sets or (with None) removes conversation-level app data under `namespace`.
     */
    func setConversationAppData(scope: String, namespace: String, bytes: Data?) throws 
    
    /**
     * Replaces the conversation's tags.
     */
    func setConversationTags(scope: String, tags: [Tag]) throws 
    
    /**
     * Sets the history mode for one scope, or the default for new scopes when `scope` is None.
     */
    func setHistoryMode(scope: String?, mode: HistoryMode) throws 
    
    /**
     * Receives device, identity and pairing events.
     */
    func setListener(listener: CoreListener?) 
    
    /**
     * Sets what this device is doing right now in a conversation, such as the progress of a
     * run, under `namespace`; None clears it. It replaces this device's previous value there.
     * Connected devices that may read the conversation get `ScopeChange::LiveState`, and one
     * that connects later gets the current value. Nothing is stored or kept for later: the
     * value is gone once this device clears it, disconnects or suspends, so set it again
     * after `resume` if it still holds. Limits are the app data ones (namespace length,
     * `max_app_data_bytes`) and 256 values per device.
     */
    func setLiveState(scope: String, namespace: String, bytes: Data?) throws 
    
    /**
     * Writes app data onto a message this user or a hosted agent authored. Each namespace
     * replaces what was there; empty bytes with no attachments clears it.
     */
    func setMessageAppData(id: String, appData: [AppDataWrite]) throws 
    
    func setPinned(scope: String, pinned: Bool) throws 
    
    /**
     * Fractional ordering for manual reorder.
     */
    func setSortOrder(scope: String, order: Double) throws 
    
    /**
     * Signs this device out of the user identity. With `keep_conversations` false this is
     * `reset`. With true, the identity is replaced, this user's other devices are revoked
     * here, and the conversations this user owned stay on this device as device-local ones;
     * conversations others shared are removed. Either way the core closes; open a new one to
     * continue (with a new identity, ready to pair).
     */
    func signOut(keepConversations: Bool) async throws 
    
    func storageUsage() throws  -> StorageUsage
    
    /**
     * Delivers message, stream and sync-status changes for one scope until cancelled.
     */
    func subscribe(scope: String, listener: ScopeListener) throws  -> Subscription
    
    /**
     * Delivers conversation list changes until cancelled.
     */
    func subscribeConversations(listener: ConversationListener)  -> Subscription
    
    /**
     * A JSON report to attach to support requests: versions, connection state, counters and
     * recent log records. Device and scope ids, addresses and device names are replaced with
     * tokens (the same id gets the same token within one report). Message content, titles and
     * keys are never in it.
     */
    func supportBundle()  -> String
    
    /**
     * Call when the app moves to the background (required on iOS). Flushes Loro snapshots,
     * checkpoints the WAL and closes the endpoint. Local reads and writes keep working; the
     * outbox waits for `resume`.
     */
    func suspend() async throws 
    
    /**
     * Dial known devices now instead of waiting for the retry interval.
     */
    func syncNow() 
    
    func syncStatus(scope: String) throws  -> SyncStatus
    
    func userKey() throws  -> String
    
    /**
     * Rebuilds a conversation as of `timestamp_ms` by replaying its events up to then.
     */
    func viewAt(scope: String, timestampMs: UInt64, limit: UInt32) throws  -> PointInTimeView
    
}
