// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum CoreEvent: Equatable, Hashable {
    
    case devicesChanged
    /**
     * This device was revoked; sync has stopped.
     */
    case selfRevoked
    /**
     * Pairing or recovery replaced the user identity; reload everything.
     */
    case identityChanged
    /**
     * A restored database for another identity was found. Prompt for its recovery phrase and
     * call `recover_from_phrase` to unlock its history.
     */
    case recoveryAvailable
    case paired(device: String
    )
    case pairingFailed(reason: String
    )
    /**
     * Pairing reached the confirmation step, on the existing device and on the new one. Show
     * `code` and ask whether the other device shows the same six digits; then call
     * `confirm_pairing(device)` or `reject_pairing(device)`. Nothing is granted until both
     * devices confirmed. `name` and `platform` are what the other device calls itself.
     */
    case pairingConfirmation(device: String, name: String, platform: Platform, code: String
    )
    case inviteResult(scope: String, error: String?
    )
    case peerRevoked(device: String
    )
    /**
     * A device that isn't this user's or a member's tried to sync and was turned away.
     */
    case peerRejected(device: String
    )
    case incompatiblePeer(device: String, version: UInt32
    )





}

#if compiler(>=6)
extension CoreEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreEvent: FfiConverterRustBuffer {
    typealias SwiftType = CoreEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .devicesChanged
        
        case 2: return .selfRevoked
        
        case 3: return .identityChanged
        
        case 4: return .recoveryAvailable
        
        case 5: return .paired(device: try FfiConverterString.read(from: &buf)
        )
        
